def algorithm(func, dim, lb, ub, budget, rng):
    best_x = np.zeros(dim)
    best_fx = float('inf')

    for _ in range(budget):
        x = np.clip(rng.uniform(lb, ub, size=dim), a_min=lb, a_max=ub)
        fx = func(x)

        if fx < best_fx:
            best_x = x
            best_fx = fx

    return best_x
